        byte* pBytes = pHeap->Allocate( nSize * sizeof(T) );
        if( !pBytes )
            pBytes = reinterpret_cast<byte*>( FMALLOC( nSize*sizeof(T), POOL, TAG ) );

        m_pAlloc = reinterpret_cast<T*>(pBytes);       
