        const byte* pAlloc = reinterpret_cast<const byte*>( m_pAlloc );
        if( pHeap->OwnsAllocation( pAlloc  ) )
            pHeap->DeAllocate( pAlloc );
        else
            FFREE( reinterpret_cast<void*>( m_pAlloc ) );
    }

