void CvDllGameContext::InitializeSingleton()
{
	if(s_pSingleton != NULL) return;
	if(s_hHeap != INVALID_HANDLE_VALUE) { SetLastError(ERROR_BUSY); throw std::bad_alloc(); }
	HANDLE heap = HeapCreate(0, 0, 0);
	if(heap == NULL) throw std::bad_alloc();
	s_hHeap = heap;
	ULONG information = 2;
	HeapSetInformation(s_hHeap, HeapCompatibilityInformation, &information, sizeof(information));
	try
	{
		s_pSingleton = FNEW(CvDllGameContext(), c_eCiv5GameplayDLL, 0);
		if(s_pSingleton == NULL) throw std::bad_alloc();
	}
	catch(...)
