bool CvDllDatabaseUtility::PerformDatabasePostProcessing()
{
	//Insert any database methods that you would like performed after the database
	//has been fully loaded.  This method will execute every single time the game
	//is run.
	//Updates performed here are done AFTER the database has been built or read
	//from cache.
	Database::Connection* db = GC.GetGameDatabase();

	//Update Defines table from references in PostDefines table
	db->BeginTransaction();
	Database::Results kPostDefines;

	//Build insertion statement
	Database::Results kInsert;
	db->Execute(kInsert, "INSERT OR REPLACE INTO Defines(Name, Value) VALUES(?, ?)");

	db->SelectAll(kPostDefines, "PostDefines");
	while(kPostDefines.Step())
	{
		const char* szName = kPostDefines.GetText("Name");
		const char* szKeyName = kPostDefines.GetText("Key");
		const char* szTableName = kPostDefines.GetText("Table");
		char szSQL[512];

		sprintf_s(szSQL, "select ROWID from %s where Type = '%s' LIMIT 1", szTableName, szKeyName);

		Database::Results kLookup;

		//Compile the command.
		if(db->Execute(kLookup, szSQL))
		{
			//Run the command.
			if(kLookup.Step())
			{
				//Perform insertion
				kInsert.Bind(1, szName);
				kInsert.Bind(2, kLookup.GetInt(0));
				kInsert.Step();
				kInsert.Reset();
			}
		}
	}

	// ** Modify ResourceUsage of Resources table **
	// Set ResourceUsage to 1 if it's referenced in Unit_ResourceQuantityRequirements
	// NOTE: This query could be simplified using the IN operator but when analyzed this
	//			statement generates faster operations.
	const char* szStrategicResource
	    = "UPDATE Resources SET ResourceUsage = 1 WHERE EXISTS (SELECT * FROM Unit_ResourceQuantityRequirements WHERE ResourceType = Type)";
	db->Execute(szStrategicResource);

	// Set ResourceUsage to 2 if the Resource has a happiness value greater than 0
	const char* szLuxoryResource
	    = "UPDATE Resources SET ResourceUsage = 2 where Happiness > 0";
	db->Execute(szLuxoryResource);

	//These are hard-coded GameDefines enum values, let's share them with the database so that they
	//get the same amount of love as the DB.
	Database::Results kInsertDefine;
	if(db->Execute(kInsertDefine, "INSERT OR REPLACE INTO Defines(Name, Value) VALUES(?, ?);"))
	{
		InsertGameDefine(kInsertDefine, "MAX_CIV_PLAYERS", MAX_CIV_PLAYERS);
		InsertGameDefine(kInsertDefine, "MAX_CIV_TEAMS", MAX_CIV_TEAMS);
		InsertGameDefine(kInsertDefine, "MAX_MAJOR_CIVS", MAX_MAJOR_CIVS);
		InsertGameDefine(kInsertDefine, "MAX_MINOR_CIVS", MAX_MINOR_CIVS);
		InsertGameDefine(kInsertDefine, "MAX_PLAYERS", MAX_PLAYERS);
		InsertGameDefine(kInsertDefine, "MAX_TEAMS", MAX_TEAMS);
		InsertGameDefine(kInsertDefine, "BARBARIAN_PLAYER", BARBARIAN_PLAYER);
		InsertGameDefine(kInsertDefine, "BARBARIAN_TEAM", BARBARIAN_TEAM);

		InsertGameDefine(kInsertDefine, "NUM_CITY_PLOTS", NUM_CITY_PLOTS);
		InsertGameDefine(kInsertDefine, "CITY_HOME_PLOT", CITY_HOME_PLOT);
		InsertGameDefine(kInsertDefine, "CITY_PLOTS_RADIUS", CITY_PLOTS_RADIUS);
		InsertGameDefine(kInsertDefine, "CITY_PLOTS_DIAMETER", CITY_PLOTS_DIAMETER);
	}

	db->EndTransaction();

	return true;
}

patches.new:
bool CvDllDatabaseUtility::PerformDatabasePostProcessing()
{
    Database::Connection* db = GC.GetGameDatabase();
    if(db == NULL) return false;
    ZeroSisPostProcessTransaction transaction(*db);
    if(!transaction.Begin()) return false;
    const bool success = [&]() -> bool
    {
        Database::Results kInsert;
        Database::Results kPostDefines;
        if(!db->Execute(kInsert, "INSERT OR REPLACE INTO Defines(Name, Value) VALUES(?, ?)")) return false;
        if(!db->SelectAll(kPostDefines, "PostDefines") || !kPostDefines.HasColumn("Name")
            || !kPostDefines.HasColumn("Key") || !kPostDefines.HasColumn("Table")) return false;
        while(kPostDefines.Step())
        {
            const char* name = kPostDefines.GetText("Name");
            const char* key = kPostDefines.GetText("Key");
            const char* table = kPostDefines.GetText("Table");
            if(name == NULL || *name == '\0' || key == NULL || table == NULL || *table == '\0') return false;
            std::string sql("SELECT ROWID FROM \"");
            for(const char* p = table; *p; ++p)
            {
                sql += *p;
                if(*p == '\"') sql += '\"';
            }
            sql += "\" WHERE Type = ? LIMIT 1";
            Database::Results lookup;
            if(!db->Execute(lookup, sql.c_str()) || !lookup.Bind(1, key)) return false;
            if(lookup.Step())
            {
                if(!InsertGameDefine(kInsert, name, lookup.GetInt(0))) return false;
            }
            // SQLite's DONE (101) means an absent optional key, not an SQL error.
            // Preserve the original behavior of leaving that define unchanged.
            else if(db->ErrorCode() != 101) return false;
        }
        if(db->ErrorCode() != 101) return false;
        kPostDefines.Release();
        kInsert.Release();
        if(!db->Execute("UPDATE Resources SET ResourceUsage = 1 WHERE EXISTS (SELECT * FROM Unit_ResourceQuantityRequirements WHERE ResourceType = Type)")) return false;
        if(!db->Execute("UPDATE Resources SET ResourceUsage = 2 where Happiness > 0")) return false;
        Database::Results kInsertDefine;
        if(!db->Execute(kInsertDefine, "INSERT OR REPLACE INTO Defines(Name, Value) VALUES(?, ?);")) return false;
        if(!InsertGameDefine(kInsertDefine, "MAX_CIV_PLAYERS", MAX_CIV_PLAYERS)) return false;
        if(!InsertGameDefine(kInsertDefine, "MAX_CIV_TEAMS", MAX_CIV_TEAMS)) return false;
        if(!InsertGameDefine(kInsertDefine, "MAX_MAJOR_CIVS", MAX_MAJOR_CIVS)) return false;
        if(!InsertGameDefine(kInsertDefine, "MAX_MINOR_CIVS", MAX_MINOR_CIVS)) return false;
        if(!InsertGameDefine(kInsertDefine, "MAX_PLAYERS", MAX_PLAYERS)) return false;
        if(!InsertGameDefine(kInsertDefine, "MAX_TEAMS", MAX_TEAMS)) return false;
        if(!InsertGameDefine(kInsertDefine, "BARBARIAN_PLAYER", BARBARIAN_PLAYER)) return false;
        if(!InsertGameDefine(kInsertDefine, "BARBARIAN_TEAM", BARBARIAN_TEAM)) return false;
        if(!InsertGameDefine(kInsertDefine, "NUM_CITY_PLOTS", NUM_CITY_PLOTS)) return false;
        if(!InsertGameDefine(kInsertDefine, "CITY_HOME_PLOT", CITY_HOME_PLOT)) return false;
        if(!InsertGameDefine(kInsertDefine, "CITY_PLOTS_RADIUS", CITY_PLOTS_RADIUS)) return false;
        if(!InsertGameDefine(kInsertDefine, "CITY_PLOTS_DIAMETER", CITY_PLOTS_DIAMETER)) return false;
        return true;
    }();
    if(success && transaction.Commit()) return true;
    if(!transaction.Rollback()) throw std::runtime_error("GameCore postprocessing rollback failed; discard this database connection");
    return false;
}

