public:

void CvDllGameContext::Init()
{
    ZeroSisHostBinding::Lease mutation(ZeroSisHostBinding::ProcessGate());
    if(!mutation) throw std::logic_error("GameCore lifecycle mutation is busy");
    ZeroSisGlobalsLifecycle::ProcessState().Initialize(&GC, [&]() { GC.init(); }, [&]() { GC.uninit(); });
}

void CvDllGameContext::Uninit()
{
    ZeroSisHostBinding::Lease mutation(ZeroSisHostBinding::ProcessGate());
    if(!mutation) throw std::logic_error("GameCore lifecycle mutation is busy");
    ZeroSisGlobalsLifecycle::ProcessState().Uninitialize(&GC, [&]() { GC.uninit(); });
}

