int CvFractal::yieldX(int iBadX)
{
    if (m_iFracX <= 0) throw std::logic_error("Fractal is not initialized");
    const int wrapped = iBadX % m_iFracX;
    return wrapped < 0 ? wrapped + m_iFracX : wrapped;
}

