void CvReplayMessage::write(FDataStream& kStream) const
{
	// Validate every selected count before output; match the original reader width.
	const int iNumPlots = CvChecked::Integer<int>(m_Plots.size());

	kStream << m_iTurn;
	kStream << m_eType;

	kStream << iNumPlots;
	PlotPositionList::const_iterator it = m_Plots.begin();
	for(int iPlot = 0; iPlot < iNumPlots; ++iPlot, ++it)
	{
		kStream << (*it).first;
		kStream << (*it).second;
	}

	kStream << m_ePlayer;
	kStream << m_strText;
}
